-- 0140: Demon Slayer — Kokushibo entwickelte das Mond-Atmen schon als Mensch
-- (Michikatsu Tsugikuni, selbst Dämonenjäger), nicht als Dämon. Idempotent.
update question_translations set explanation = 'As Michikatsu Tsugikuni, he derived it from his twin brother Yoriichi’s Sun Breathing.', prompt = 'Which breathing style did Kokushibo create while still a human demon slayer?' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Como Michikatsu Tsugikuni, la derivó de la Respiración del Sol de su gemelo Yoriichi.', prompt = '¿Qué técnica de respiración creó Kokushibo cuando aún era un cazador de demonios humano?' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Sous le nom de Michikatsu Tsugikuni, il l’a dérivé du Souffle du Soleil de son jumeau Yoriichi.', prompt = 'Quel souffle Kokushibo a-t-il créé quand il était encore un pourfendeur de démons humain ?' where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Como Michikatsu Tsugikuni, ele o derivou da Respiração do Sol de seu gêmeo Yoriichi.', prompt = 'Qual estilo de respiração Kokushibo criou quando ainda era um caçador de demônios humano?' where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Come Michikatsu Tsugikuni, la derivò dalla Respirazione del Sole del gemello Yoriichi.', prompt = 'Quale respirazione creò Kokushibo quando era ancora un ammazzademoni umano?' where lang = 'it' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Sebagai Michikatsu Tsugikuni, ia mengembangkannya dari Pernapasan Matahari milik saudara kembarnya, Yoriichi.', prompt = 'Teknik pernapasan apa yang diciptakan Kokushibo saat masih menjadi pembasmi iblis manusia?' where lang = 'id' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Michikatsu Tsugikuni olarak bunu ikiz kardeşi Yoriichi’nin Güneş Nefesi’nden türetti.', prompt = 'Kokushibo henüz insan bir iblis avcısıyken hangi nefes tekniğini geliştirdi?' where lang = 'tr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Jako Michikatsu Tsugikuni wywiódł go z Oddechu Słońca swojego bliźniaka Yoriichiego.', prompt = 'Jaki styl oddechu stworzył Kokushibo, gdy był jeszcze ludzkim zabójcą demonów?' where lang = 'pl' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Khi còn là Tsugikuni Michikatsu, anh ta phát triển nó từ Hơi thở Mặt Trời của em song sinh Yoriichi.', prompt = 'Kokushibo đã tạo ra hơi thở nào khi còn là một kiếm sĩ diệt quỷ loài người?' where lang = 'vi' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = '継国巌勝として、双子の弟・縁壱の日の呼吸から派生させました。', prompt = '黒死牟が人間の鬼殺隊士だった頃に生み出した呼吸は？' where lang = 'ja' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = '츠기쿠니 미치카츠였던 그는 쌍둥이 동생 요리이치의 해의 호흡에서 이를 파생시켰어요.', prompt = '코쿠시보가 아직 인간 귀살대원이던 시절 만든 호흡은?' where lang = 'ko' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'ในฐานะสึงิคุนิ มิจิคัตสึ เขาพัฒนามาจากปราณตะวันของโยริอิจิ น้องชายฝาแฝด', prompt = 'โคคุชิโบสร้างปราณแบบใดขึ้นตอนที่ยังเป็นนักล่าอสูรที่เป็นมนุษย์?' where lang = 'th' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Будучи Мичикацу Цугикуни, он вывел его из Дыхания Солнца своего брата-близнеца Ёриичи.', prompt = 'Какое дыхание Кокушибо создал, ещё будучи человеком-охотником на демонов?' where lang = 'ru' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'بصفته ميتشيكاتسو تسوغيكوني، اشتقّه من تنفّس الشمس لأخيه التوأم يوريئتشي.', prompt = 'ما أسلوب التنفس الذي ابتكره كوكوشيبو حين كان لا يزال صائد شياطين بشريًا؟' where lang = 'ar' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
update question_translations set explanation = 'Als Michikatsu Tsugikuni leitete er sie vom Sonnen-Atmen seines Zwillingsbruders Yoriichi ab.', prompt = 'Welche Atemtechnik entwickelte Kokushibo noch als menschlicher Dämonenjäger?' where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Atemtechnik entwickelte Kokushibo als Dämon?');
